import fitz, numpy as np
d = fitz.open('eprint/figures/sn1987a_alp_conversion_limits.pdf')
p = d[0]
draws = p.get_drawings()

# calibration from tick label centers
# x: log10(m): -11 at 44.25, -10 at 88.75, -9 at 133.35, -8 at 177.85
import numpy as np
xt = np.array([44.25, 88.75, 133.35, 177.85]); xv = np.array([-11,-10,-9,-8])
ax, bx = np.polyfit(xt, xv, 1)
yt = np.array([154.3, 79.3, 4.4]); yv = np.array([-12,-11,-10])
ay, by = np.polyfit(yt, yv, 1)

def pts_of(dr):
    pts=[]
    for it in dr['items']:
        if it[0]=='l':
            pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
        elif it[0]=='c':
            for pt in it[1:5]: pts.append((pt.x,pt.y))
    # dedupe consecutive
    out=[]
    for q in pts:
        if not out or abs(out[-1][0]-q[0])>1e-6 or abs(out[-1][1]-q[1])>1e-6:
            out.append(q)
    return out

for i,dr in enumerate(draws):
    col=dr.get('color'); n=len(dr['items'])
    if dr['type'] in ('s','fs') and n>40:
        pts=pts_of(dr)
        xs=[q[0] for q in pts]; ys=[q[1] for q in pts]
        print(i, col, n, 'x:',round(min(xs),1),round(max(xs),1),'y:',round(min(ys),1),round(max(ys),1))

# black curve
for i,dr in enumerate(draws):
    if dr.get('color')==(0.0,0.0,0.0) and len(dr['items'])==76:
        pts=pts_of(dr)
        print('\nBLACK curve, %d pts'%len(pts))
        for q in pts[:5]+pts[-5:]:
            m=10**(ax*q[0]+bx); g=10**(ay*q[1]+by)
            print(f'{m:.3e} {g:.3e}')
