python3 << 'EOF'
import fitz, numpy as np, json
d = fitz.open('eprint/figures/sn1987a_alp_conversion_limits.pdf')
p = d[0]
draws = p.get_drawings()

def logm(x): return -11 + (x-44.49)/((178.12-44.49)/3)
def logg(y): return -12 + (154.6-y)/((154.6-4.74)/2)

arr=None
for dr in draws:
    if dr.get('color')==(0.0,0.0,0.0) and len(dr['items'])==76 and dr['type']=='s':
        pts=[]
        for it in dr['items']:
            if it[0]=='l':
                for q in (it[1],it[2]):
                    if not pts or abs(pts[-1][0]-q.x)>1e-6 or abs(pts[-1][1]-q.y)>1e-6:
                        pts.append((q.x,q.y))
        arr=np.array(pts)
        break
print('raw pts:', len(arr))
print('monotonic x:', np.all(np.diff(arr[:,0])>=0))
lm = logm(arr[:,0]); lg = logg(arr[:,1])
print('m range: %.3e %.3e'%(10**lm.min(),10**lm.max()))
print('g range: %.3e %.3e'%(10**lg.min(),10**lg.max()))
lmi = np.linspace(lm.min(), lm.max(), 50)
lgi = np.interp(lmi, lm, lg)
data = [[float(10**a), float(10**b)] for a,b in zip(lmi,lgi)]
for i in range(0,50,4): print(f'{data[i][0]:.4e} {data[i][1]:.4e}')
print(f'{data[-1][0]:.4e} {data[-1][1]:.4e}')
json.dump(data, open('conv_curve.json','w'))
EOF
